recipes.code:
{
  "inputs": [
    {
      "id": "hpsilab-api-key",
      "type": "promptString",
      "description": "HPSILab API key (hpsi_...) from hpsilab.com settings",
      "password": true
    }
  ],
  "servers": {
    "hpsilab-quant-finance": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "hpsilab-quant-finance-mcp@0.7.2"
      ],
      "env": {
        "HPSILAB_API_KEY": "${input:hpsilab-api-key}"
      }
    }
  }
}
